$$;

CREATE SEQUENCE atin_seq
    START WITH 1000
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE brand (
    id uuid NOT NULL,
    name character varying(120) NOT NULL,
    normalized_name character varying(120) NOT NULL,
    status character varying(20) NOT NULL,
    merged_into_id uuid,
    created_by_org character varying(80),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    decided_by character varying(120),
    decided_at timestamp with time zone,
    decision_reason text,
    CONSTRAINT brand_check CHECK ((((status)::text = 'MERGED_INTO'::text) = (merged_into_id IS NOT NULL))),
    CONSTRAINT brand_status_check CHECK (status IN ('APPROVED', 'PENDING', 'REJECTED', 'MERGED_INTO', 'RETIRED'))
);

CREATE TABLE brand_scope (
    brand_id uuid NOT NULL,
    node_id uuid NOT NULL
);

CREATE TABLE category (
    id uuid NOT NULL,
    parent_id uuid,
    name character varying(120) NOT NULL,
    level character varying(20) NOT NULL,
    product_type_code character varying(40),
    path character varying(400) NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    code character varying(120) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    retired_at timestamp with time zone,
    retired_reason text,
    updated_at timestamp with time zone,
    compliance character varying(200),
    tax_profile_id character varying(80),
    tax_status character varying(20),
    CONSTRAINT category_level_check CHECK (level IN ('DEPARTMENT', 'CATEGORY', 'PRODUCT_TYPE')),
    CONSTRAINT category_tax_status_check CHECK (tax_status IN ('ACTIVE', 'NEEDS_APPROVAL', 'BLOCKED_BUNDLE', 'REFINE_CODE', 'CONFLICT_OPEN'))
);

CREATE TABLE category_request (
    id uuid NOT NULL,
    reference character varying(20) NOT NULL,
    requested_by_org character varying(80) NOT NULL,
    parent_path character varying(200) NOT NULL,
    name character varying(80) NOT NULL,
    example_product character varying(200) NOT NULL,
    details_needed text NOT NULL,
    status character varying(20) NOT NULL,
    resolved_category_id uuid,
    decision_note text,
    created_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL
);

CREATE SEQUENCE category_request_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE listing_enforcement_run (
    event_id uuid NOT NULL,
    org_id character varying(80) NOT NULL,
    action character varying(10) NOT NULL,
    reason character varying(40) NOT NULL,
    status character varying(12) NOT NULL,
    cursor_product_id uuid,
    processed integer DEFAULT 0 NOT NULL,
    pages integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT listing_enforcement_run_action CHECK (action IN ('HIDE', 'RESTORE')),
    CONSTRAINT listing_enforcement_run_status CHECK (status IN ('RUNNING', 'DONE', 'SUPERSEDED'))
);

CREATE TABLE org_listing_suppression (
    org_id character varying(80) NOT NULL,
    hidden boolean NOT NULL,
    reason character varying(40) NOT NULL,
    changed_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE product (
    id uuid NOT NULL,
    atin character(10) NOT NULL,
    owner_kind character varying(10) NOT NULL,
    owner_org character varying(80) NOT NULL,
    category_id uuid,
    category_request_id uuid,
    product_type character varying(40) NOT NULL,
    title character varying(200) NOT NULL,
    attributes jsonb NOT NULL,
    images jsonb NOT NULL,
    variation_theme character varying(60) NOT NULL,
    status character varying(30) NOT NULL,
    moderation_note text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    preorder_eligible boolean DEFAULT false NOT NULL,
    ships_now boolean DEFAULT false NOT NULL,
    listing jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT product_owner_kind_check CHECK (owner_kind IN ('SELLER', 'PLATFORM'))
);

CREATE TABLE product_data_lookup (
    gtin character varying(14) NOT NULL,
    found boolean NOT NULL,
    results jsonb NOT NULL,
    fetched_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL
);

CREATE TABLE product_draft (
    id uuid NOT NULL,
    owner_org character varying(80) NOT NULL,
    created_by character varying(120) NOT NULL,
    product_id uuid,
    title character varying(200) DEFAULT ''::character varying NOT NULL,
    category_path character varying(400),
    payload jsonb NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL
);

CREATE TABLE product_flag (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    owner_org character varying(80) NOT NULL,
    source character varying(20) NOT NULL,
    reason_code character varying(40) NOT NULL,
    details text,
    reporter_id character varying(160),
    risk_level character varying(20),
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT product_flag_source_check CHECK (source IN ('CUSTOMER_REPORT', 'STAFF', 'AUTOMATED'))
);

CREATE TABLE product_import (
    id uuid NOT NULL,
    reference character varying(20) NOT NULL,
    owner_kind character varying(10) NOT NULL,
    owner_org character varying(80) NOT NULL,
    uploaded_by character varying(120) NOT NULL,
    uploaded_by_name character varying(200),
    file_name character varying(200) NOT NULL,
    file_format character varying(10) NOT NULL,
    mode character varying(10) NOT NULL,
    product_type character varying(40),
    header jsonb NOT NULL,
    file_warnings jsonb DEFAULT '[]'::jsonb NOT NULL,
    status character varying(30) NOT NULL,
    valid_only boolean DEFAULT false NOT NULL,
    total_rows integer NOT NULL,
    valid_rows integer NOT NULL,
    warning_rows integer NOT NULL,
    error_rows integer NOT NULL,
    product_count integer NOT NULL,
    processed_rows integer DEFAULT 0 NOT NULL,
    created_products integer DEFAULT 0 NOT NULL,
    updated_products integer DEFAULT 0 NOT NULL,
    failed_rows integer DEFAULT 0 NOT NULL,
    notify boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    heartbeat_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT product_import_file_format_check CHECK (file_format IN ('XLSX', 'CSV')),
    CONSTRAINT product_import_mode_check CHECK (mode IN ('CREATE', 'UPDATE'))
);

CREATE TABLE product_import_row (
    import_id uuid NOT NULL,
    row_number integer NOT NULL,
    group_key character varying(60) NOT NULL,
    sku character varying(60) NOT NULL,
    status character varying(10) NOT NULL,
    messages jsonb NOT NULL,
    cells jsonb NOT NULL,
    outcome character varying(10) DEFAULT 'PENDING'::character varying NOT NULL,
    outcome_note text,
    product_id uuid,
    CONSTRAINT product_import_row_outcome_check CHECK (outcome IN ('PENDING', 'CREATED', 'UPDATED', 'FAILED', 'SKIPPED')),
    CONSTRAINT product_import_row_status_check CHECK (status IN ('VALID', 'WARNING', 'ERROR'))
);

CREATE SEQUENCE product_import_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE product_rating (
    product_id uuid NOT NULL,
    atin character(10) NOT NULL,
    average numeric(3,2) NOT NULL,
    review_count integer NOT NULL,
    star1 integer NOT NULL,
    star2 integer NOT NULL,
    star3 integer NOT NULL,
    star4 integer NOT NULL,
    star5 integer NOT NULL,
    updated_at timestamp with time zone NOT NULL
);

CREATE TABLE product_review (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    atin character(10) NOT NULL,
    product_title character varying(200) NOT NULL,
    seller_org_id character varying(80) NOT NULL,
    customer_id character varying(80) NOT NULL,
    reviewer_name character varying(120) NOT NULL,
    order_id character varying(80) NOT NULL,
    order_number character varying(40) NOT NULL,
    rating smallint NOT NULL,
    title character varying(120),
    body text,
    photos jsonb DEFAULT '[]'::jsonb NOT NULL,
    status character varying(12) NOT NULL,
    flags character varying(120) DEFAULT ''::character varying NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    moderated_by character varying(120),
    moderated_at timestamp with time zone,
    moderation_reason character varying(30),
    moderation_note text,
    reply_text text,
    reply_by character varying(120),
    reply_at timestamp with time zone,
    report_count integer DEFAULT 0 NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT product_review_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT product_review_status_check CHECK (status IN ('PENDING', 'PUBLISHED', 'REJECTED', 'REMOVED', 'DELETED'))
);

CREATE TABLE product_review_report (
    id uuid NOT NULL,
    review_id uuid NOT NULL,
    reporter_id character varying(80) NOT NULL,
    reporter_kind character varying(10) NOT NULL,
    reason_code character varying(30) NOT NULL,
    details text,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT product_review_report_reporter_kind_check CHECK (reporter_kind IN ('CUSTOMER', 'SELLER'))
);

CREATE TABLE product_takedown (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    reason_code character varying(40) NOT NULL,
    note text,
    actor_id character varying(160) NOT NULL,
    previous_status character varying(30) NOT NULL,
    taken_down_at timestamp with time zone NOT NULL,
    restored_at timestamp with time zone,
    restored_by character varying(160),
    restore_note text,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT product_takedown_previous_status_check CHECK (previous_status IN ('LIVE', 'PAUSED'))
);

CREATE TABLE product_type (
    code character varying(40) NOT NULL,
    label character varying(120) NOT NULL,
    identifier_rule character varying(10) NOT NULL,
    attributes jsonb NOT NULL,
    themes jsonb NOT NULL,
    traits jsonb DEFAULT '{}'::jsonb NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone,
    CONSTRAINT product_type_identifier_rule_check CHECK (identifier_rule IN ('GTIN', 'ISBN'))
);

CREATE TABLE product_variant (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    atin character(10) NOT NULL,
    owner_org character varying(80) NOT NULL,
    seller_sku character varying(40) NOT NULL,
    gtin character varying(14),
    gtin_exempt boolean DEFAULT false NOT NULL,
    options jsonb NOT NULL,
    price_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    quantity integer NOT NULL,
    "position" integer NOT NULL,
    compare_at_minor bigint,
    images jsonb DEFAULT '[]'::jsonb NOT NULL,
    seller_sku_generated boolean DEFAULT false NOT NULL,
    tax_facts jsonb DEFAULT '{}'::jsonb NOT NULL,
    tax_status character varying(20) DEFAULT 'MISSING_FACTS'::character varying NOT NULL,
    missing_tax_facts jsonb DEFAULT '[]'::jsonb NOT NULL,
    tax_decision jsonb,
    CONSTRAINT product_variant_compare_at_minor_check CHECK (((compare_at_minor IS NULL) OR (compare_at_minor > 0))),
    CONSTRAINT product_variant_price_minor_check CHECK ((price_minor > 0)),
    CONSTRAINT product_variant_quantity_check CHECK ((quantity >= 0))
);

CREATE TABLE size_chart (
    id uuid NOT NULL,
    owner_org character varying(80) NOT NULL,
    name character varying(80) NOT NULL,
    unit_system character varying(2) NOT NULL,
    product_type_code character varying(40),
    category_id uuid,
    columns jsonb NOT NULL,
    rows jsonb NOT NULL,
    fit_note character varying(20),
    how_to_measure text,
    retired_at timestamp with time zone,
    created_by character varying(120) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT size_chart_fit_note_check CHECK (fit_note IN ('RUNS_SMALL', 'TRUE_TO_SIZE', 'RUNS_LARGE')),
    CONSTRAINT size_chart_unit_system_check CHECK (unit_system IN ('CM', 'IN'))
);

CREATE TABLE taxonomy_audit (
    id uuid NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    actor_id character varying(120) NOT NULL,
    action character varying(40) NOT NULL,
    subject_kind character varying(20) NOT NULL,
    subject_id character varying(80) NOT NULL,
    subject_label character varying(400) NOT NULL,
    reason text NOT NULL,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT taxonomy_audit_subject_kind_check CHECK (subject_kind IN ('NODE', 'PRODUCT_TYPE', 'REQUEST', 'BRAND'))
);

CREATE TABLE unit_label (
    code character(10) NOT NULL,
    owner_org character varying(80) NOT NULL,
    atin character(10) NOT NULL,
    created_at timestamp with time zone NOT NULL
);

CREATE SEQUENCE unit_label_seq
    START WITH 1000
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE variant_tax_evidence (
    id uuid NOT NULL,
    variant_atin character(10) NOT NULL,
    owner_org character varying(80) NOT NULL,
    fact_id character varying(60) NOT NULL,
    version integer NOT NULL,
    file_name character varying(200) NOT NULL,
    content_type character varying(80) NOT NULL,
    bytes bigint NOT NULL,
    content bytea NOT NULL,
    uploaded_by character varying(120) NOT NULL,
    uploaded_at timestamp with time zone NOT NULL,
    CONSTRAINT variant_tax_evidence_bytes_check CHECK ((bytes > 0))
);

ALTER TABLE ONLY brand
    ADD CONSTRAINT brand_pkey PRIMARY KEY (id);

ALTER TABLE ONLY brand_scope
    ADD CONSTRAINT brand_scope_pkey PRIMARY KEY (brand_id, node_id);

ALTER TABLE ONLY category
    ADD CONSTRAINT category_parent_id_name_key UNIQUE (parent_id, name);

ALTER TABLE ONLY category
    ADD CONSTRAINT category_pkey PRIMARY KEY (id);

ALTER TABLE ONLY category_request
    ADD CONSTRAINT category_request_pkey PRIMARY KEY (id);

ALTER TABLE ONLY category_request
    ADD CONSTRAINT category_request_reference_key UNIQUE (reference);

ALTER TABLE ONLY listing_enforcement_run
    ADD CONSTRAINT listing_enforcement_run_pkey PRIMARY KEY (event_id);

ALTER TABLE ONLY org_listing_suppression
    ADD CONSTRAINT org_listing_suppression_pkey PRIMARY KEY (org_id);

ALTER TABLE ONLY product
    ADD CONSTRAINT product_atin_key UNIQUE (atin);

ALTER TABLE ONLY product_data_lookup
    ADD CONSTRAINT product_data_lookup_pkey PRIMARY KEY (gtin);

ALTER TABLE ONLY product_draft
    ADD CONSTRAINT product_draft_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_flag
    ADD CONSTRAINT product_flag_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_import
    ADD CONSTRAINT product_import_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_import
    ADD CONSTRAINT product_import_reference_key UNIQUE (reference);

ALTER TABLE ONLY product_import_row
    ADD CONSTRAINT product_import_row_pkey PRIMARY KEY (import_id, row_number);

ALTER TABLE ONLY product
    ADD CONSTRAINT product_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_rating
    ADD CONSTRAINT product_rating_pkey PRIMARY KEY (product_id);

ALTER TABLE ONLY product_review
    ADD CONSTRAINT product_review_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_review_report
    ADD CONSTRAINT product_review_report_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_review_report
    ADD CONSTRAINT product_review_report_review_id_reporter_id_key UNIQUE (review_id, reporter_id);

ALTER TABLE ONLY product_takedown
    ADD CONSTRAINT product_takedown_pkey PRIMARY KEY (id);

ALTER TABLE ONLY product_type
    ADD CONSTRAINT product_type_pkey PRIMARY KEY (code);

ALTER TABLE ONLY product_variant
    ADD CONSTRAINT product_variant_atin_key UNIQUE (atin);

ALTER TABLE ONLY product_variant
    ADD CONSTRAINT product_variant_owner_org_seller_sku_key UNIQUE (owner_org, seller_sku);

ALTER TABLE ONLY product_variant
    ADD CONSTRAINT product_variant_pkey PRIMARY KEY (id);

ALTER TABLE ONLY size_chart
    ADD CONSTRAINT size_chart_pkey PRIMARY KEY (id);

ALTER TABLE ONLY taxonomy_audit
    ADD CONSTRAINT taxonomy_audit_pkey PRIMARY KEY (id);

ALTER TABLE ONLY unit_label
    ADD CONSTRAINT unit_label_owner_org_atin_key UNIQUE (owner_org, atin);

ALTER TABLE ONLY unit_label
    ADD CONSTRAINT unit_label_pkey PRIMARY KEY (code);

ALTER TABLE ONLY variant_tax_evidence
    ADD CONSTRAINT variant_tax_evidence_pkey PRIMARY KEY (id);

ALTER TABLE ONLY variant_tax_evidence
    ADD CONSTRAINT variant_tax_evidence_variant_atin_fact_id_version_key UNIQUE (variant_atin, fact_id, version);

CREATE INDEX brand_created_by_org ON brand USING btree (created_by_org) WHERE (created_by_org IS NOT NULL);

CREATE INDEX brand_normalized ON brand USING btree (normalized_name);

CREATE INDEX brand_scope_node ON brand_scope USING btree (node_id);

CREATE INDEX brand_status ON brand USING btree (status, created_at);

CREATE UNIQUE INDEX category_code ON category USING btree (code);

CREATE INDEX category_parent ON category USING btree (parent_id, "position");

CREATE INDEX category_request_org ON category_request USING btree (requested_by_org);

CREATE INDEX category_request_status ON category_request USING btree (status);

CREATE UNIQUE INDEX category_sibling_name ON category USING btree (COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower((name)::text));

CREATE INDEX category_tax_profile ON category USING btree (tax_profile_id) WHERE (tax_profile_id IS NOT NULL);

CREATE INDEX listing_enforcement_run_running ON listing_enforcement_run USING btree (org_id, updated_at) WHERE ((status)::text = 'RUNNING'::text);

CREATE INDEX org_listing_suppression_hidden ON org_listing_suppression USING btree (org_id) WHERE hidden;

CREATE INDEX product_brand_id ON product USING btree (((attributes ->> 'brand_id'::text))) WHERE ((attributes ->> 'brand_id'::text) IS NOT NULL);

CREATE INDEX product_category ON product USING btree (category_id) WHERE (category_id IS NOT NULL);

CREATE INDEX product_category_request ON product USING btree (category_request_id) WHERE (category_request_id IS NOT NULL);

CREATE INDEX product_draft_owner ON product_draft USING btree (owner_org, updated_at DESC);

CREATE UNIQUE INDEX product_draft_product ON product_draft USING btree (product_id) WHERE (product_id IS NOT NULL);

CREATE UNIQUE INDEX product_flag_customer ON product_flag USING btree (product_id, reporter_id) WHERE ((source)::text = 'CUSTOMER_REPORT'::text);

CREATE INDEX product_flag_product ON product_flag USING btree (product_id, created_at DESC);

CREATE INDEX product_import_owner ON product_import USING btree (owner_org, created_at DESC);

CREATE INDEX product_import_row_group ON product_import_row USING btree (import_id, group_key);

CREATE UNIQUE INDEX product_import_row_sku ON product_import_row USING btree (import_id, sku) WHERE (((sku)::text <> ''::text) AND ((status)::text <> 'ERROR'::text));

CREATE INDEX product_import_running ON product_import USING btree (status, heartbeat_at) WHERE status IN ('QUEUED', 'RUNNING');

CREATE INDEX product_owner ON product USING btree (owner_org, created_at DESC);

CREATE INDEX product_owner_id ON product USING btree (owner_org, id);

CREATE INDEX product_review_customer ON product_review USING btree (customer_id, created_at DESC) WHERE ((status)::text <> 'DELETED'::text);

CREATE UNIQUE INDEX product_review_one_per_customer ON product_review USING btree (product_id, customer_id) WHERE ((status)::text <> 'DELETED'::text);

CREATE INDEX product_review_public ON product_review USING btree (product_id, created_at DESC) WHERE ((status)::text = 'PUBLISHED'::text);

CREATE INDEX product_review_public_rating ON product_review USING btree (product_id, rating, created_at DESC) WHERE ((status)::text = 'PUBLISHED'::text);

CREATE INDEX product_review_seller ON product_review USING btree (seller_org_id, created_at DESC) WHERE ((status)::text = 'PUBLISHED'::text);

CREATE INDEX product_review_status ON product_review USING btree (status, created_at);

CREATE INDEX product_size_chart ON product USING btree (((listing ->> 'sizeChartId'::text))) WHERE (listing ? 'sizeChartId'::text);

CREATE INDEX product_status ON product USING btree (status);

CREATE UNIQUE INDEX product_takedown_active ON product_takedown USING btree (product_id) WHERE (restored_at IS NULL);

CREATE INDEX product_variant_gtin ON product_variant USING btree (gtin) WHERE (gtin IS NOT NULL);

CREATE INDEX product_variant_product ON product_variant USING btree (product_id, "position");

CREATE INDEX product_variant_tax_status ON product_variant USING btree (tax_status);

CREATE INDEX size_chart_owner ON size_chart USING btree (owner_org, updated_at DESC);

CREATE UNIQUE INDEX size_chart_owner_name ON size_chart USING btree (owner_org, lower((name)::text)) WHERE (retired_at IS NULL);

CREATE INDEX taxonomy_audit_subject ON taxonomy_audit USING btree (subject_id, occurred_at DESC);

CREATE INDEX taxonomy_audit_time ON taxonomy_audit USING btree (occurred_at DESC);

CREATE INDEX variant_tax_evidence_variant ON variant_tax_evidence USING btree (variant_atin, fact_id, version DESC);

ALTER TABLE ONLY brand
    ADD CONSTRAINT brand_merged_into_id_fkey FOREIGN KEY (merged_into_id) REFERENCES brand(id);

ALTER TABLE ONLY brand_scope
    ADD CONSTRAINT brand_scope_brand_id_fkey FOREIGN KEY (brand_id) REFERENCES brand(id) ON DELETE CASCADE;

ALTER TABLE ONLY brand_scope
    ADD CONSTRAINT brand_scope_node_id_fkey FOREIGN KEY (node_id) REFERENCES category(id);

ALTER TABLE ONLY category
